insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'multiple_choice', 'She ___ in a big IT company.', array['work', 'works', 'working']::text[], 'works', array[]::text[], 'She → +s: works.'),
  (2, 'fill_blank', 'The office ___ at nine o''clock. (open)', null::text[], 'opens', array[]::text[], 'The office = it → opens.'),
  (3, 'fill_blank', 'He ___ his code before every commit. (test)', null::text[], 'tests', array[]::text[], 'He → tests. Регулярное действие — present simple.'),
  (4, 'fill_blank', 'My brother ___ computer science at university. (study)', null::text[], 'studies', array[]::text[], 'Согласная + y → -ies: studies.'),
  (5, 'fill_blank', 'Tom ___ to work by bike. (go)', null::text[], 'goes', array[]::text[], 'go → goes (после o добавляем -es).'),
  (6, 'multiple_choice', 'We ___ a standup every morning.', array['have', 'has', 'having']::text[], 'have', array[]::text[], 'We → have. Has только с he/she/it.'),
  (7, 'multiple_choice', 'The app ___ on Android and iOS.', array['run', 'runs', 'running']::text[], 'runs', array[]::text[], 'The app = it → runs.'),
  (8, 'fill_blank', 'Our team lead ___ every pull request. (review)', null::text[], 'reviews', array[]::text[], 'Our team lead = he/she → reviews.'),
  (9, 'fill_blank', 'He ___ two languages. (speak)', null::text[], 'speaks', array[]::text[], 'He → speaks.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 5
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
