  (3, 'multiple_choice', 'Where ___ your team lead live?', array['do', 'does', 'is']::text[], 'does', array[]::text[], 'Your team lead = he/she → Where does… live?'),
  (4, 'multiple_choice', 'What does this error ___?', array['mean', 'means', 'meaning']::text[], 'mean', array[]::text[], 'После does глагол без -s: What does it mean?'),
  (5, 'multiple_choice', '''Do you use Git?'' ''Yes, I ___.''', array['do', 'does', 'am']::text[], 'do', array[]::text[], 'Вопрос с do → Yes, I do.'),
  (6, 'multiple_choice', '''Does Anna speak English?'' ''No, she ___.''', array['don''t', 'doesn''t', 'isn''t']::text[], 'doesn''t', array[]::text[], 'Вопрос с does → No, she doesn''t.'),
  (7, 'fill_blank', 'How often ___ you deploy to production? (do/does)', null::text[], 'do', array[]::text[], 'You → do.'),
  (8, 'fill_blank', 'What time ___ the standup start? (do/does)', null::text[], 'does', array[]::text[], 'The standup = it → does.')
