  (3, 'multiple_choice', '___ you got a minute?', array['Have', 'Do', 'Has']::text[], 'Have', array[]::text[], 'Have you got…? (с got вопрос строится через have).'),
  (4, 'multiple_choice', 'Do you ___ a GitHub account?', array['have', 'has', 'got']::text[], 'have', array[]::text[], 'Do you have…? После do — have.'),
  (5, 'multiple_choice', 'He ___ got a car.', array['hasn''t', 'haven''t', 'doesn''t']::text[], 'hasn''t', array[]::text[], 'He → hasn''t got.'),
  (6, 'multiple_choice', 'We ___ much time before the deadline.', array['don''t have', 'doesn''t have', 'not have']::text[], 'don''t have', array[]::text[], 'We → don''t have.'),
  (7, 'multiple_choice', '''Has your phone got a good camera?'' ''Yes, it ___.''', array['has', 'have', 'does']::text[], 'has', array[]::text[], 'Вопрос с has → Yes, it has.'),
