  (3, 'multiple_choice', '___ you at the meeting on Monday?', array['Was', 'Were', 'Did']::text[], 'Were', array[]::text[], 'You → Were you…?'),
  (4, 'fill_blank', 'The weather ___ nice last weekend. (be, отрицание)', null::text[], 'wasn''t', array['was not']::text[], 'It → was not / wasn''t.'),
  (5, 'multiple_choice', 'Where ___ you at ten o''clock?', array['was', 'were', 'did']::text[], 'were', array[]::text[], 'You → were.'),
  (6, 'multiple_choice', '''Was the demo good?'' ''Yes, it ___.''', array['was', 'were', 'did']::text[], 'was', array[]::text[], 'Вопрос с was → Yes, it was.'),
  (7, 'fill_blank', 'We ___ tired after the release. (be)', null::text[], 'were', array[]::text[], 'We → were.'),
  (8, 'multiple_choice', 'Why ___ Tom late this morning?', array['was', 'were', 'did']::text[], 'was', array[]::text[], 'Tom = he → was.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 10
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'fill_blank', 'Yesterday I ___ until 7 p.m. (work)', null::text[], 'worked', array[]::text[], 'Правильный глагол: work → worked.'),
  (2, 'fill_blank', 'We ___ the bug last week. (fix)', null::text[], 'fixed', array[]::text[], 'fix → fixed.'),
  (3, 'fill_blank', 'She ___ to London in 2019. (go)', null::text[], 'went', array[]::text[], 'go — неправильный: went.'),
  (4, 'fill_blank', 'I ___ an email to the client this morning. (send)', null::text[], 'sent', array[]::text[], 'send — неправильный: sent.'),
