) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 113
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'multiple_choice', 'The plane took ___ at 7 am.', array['off', 'up', 'out']::text[], 'off', array[]::text[], 'Взлетать — take off.'),
  (2, 'multiple_choice', 'I usually get ___ at seven.', array['up', 'on', 'off']::text[], 'up', array[]::text[], 'Вставать — get up.'),
  (3, 'multiple_choice', 'We got ___ the bus near the office.', array['off', 'out', 'away']::text[], 'off', array[]::text[], 'Выйти из автобуса — get off the bus.'),
  (4, 'multiple_choice', 'Please sit ___. The meeting is starting.', array['down', 'up', 'off']::text[], 'down', array[]::text[], 'Садиться — sit down.'),
  (5, 'multiple_choice', 'Don''t give ___! You''ve almost finished the migration.', array['up', 'out', 'away']::text[], 'up', array[]::text[], 'Сдаваться — give up.'),
  (6, 'fill_blank', 'My car broke ___ on the way to the office. (сломалась)', null::text[], 'down', array[]::text[], 'Сломаться (о машине, технике) — break down.'),
  (7, 'fill_blank', 'The connection is bad. Can you speak ___? I can''t hear you. (громче)', null::text[], 'up', array['louder']::text[], 'Говорить громче — speak up.'),
  (8, 'fill_blank', 'I''m going ___ for a few minutes. I''ll be back soon. (выйти)', null::text[], 'out', array['outside']::text[], 'Выйти (из дома, офиса) — go out.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 114
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'multiple_choice', 'It''s cold outside. ___ your jacket.', array['Put on', 'Put in', 'Put up']::text[], 'Put on', array[]::text[], 'Надеть — put on.'),
  (2, 'multiple_choice', 'It''s dark in here. Can you turn ___ the light?', array['on', 'off', 'down']::text[], 'on', array[]::text[], 'Включить — turn on.'),
  (3, 'multiple_choice', 'These are my new shoes. I''d like to try ___.', array['them on', 'on them', 'on it']::text[], 'them on', array[]::text[], 'Местоимение — между глаголом и частицей: try them on.'),
  (4, 'multiple_choice', 'These old notes are useless. Can you throw ___?', array['them away', 'away them', 'away it']::text[], 'them away', array[]::text[], 'Местоимение — перед частицей: throw them away.'),
  (5, 'multiple_choice', 'Your camera is still on. Can you ___?', array['turn it off', 'turn off it', 'turn off']::text[], 'turn it off', array[]::text[], 'turn it off — местоимение посередине, объект обязателен.'),
  (6, 'fill_blank', 'Please fill ___ this form and send it back. (заполнить)', null::text[], 'in', array['out']::text[], 'Заполнить форму — fill in.'),
  (7, 'fill_blank', 'Thanks for the charger. I''ll give it ___ tomorrow. (вернуть)', null::text[], 'back', array[]::text[], 'Вернуть — give back.'),
  (8, 'fill_blank', 'Here''s the address of the test server. Write it ___. (записать)', null::text[], 'down', array[]::text[], 'Записать — write down.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 115
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

insert into texts (title, body, cefr_level, position, questions) values
  ('My Name Is Alex', 'Hello! My name is Alex. I am a developer. I work in a small team. There are five people in my team. We make software for online shops.

Every day I start work at nine o''clock. First, I read my email. Then we have a short meeting. We call it a standup. Each person answers three questions: What did I do yesterday? What will I do today? Do I have a problem?

After the standup, I write code. Sometimes I fix a bug. Sometimes I work on a new feature. I like my work because every day is different.', 'A1', 1, '[{"statement":"Alex works in a big team of fifty people.","answer":false},{"statement":"The standup is a short meeting.","answer":true}]'::jsonb),
  ('A Bug in the App', 'Maria is a tester. She tests the app before every release. Today she has a problem. The app does not open on her phone. She sees an error on the screen.

Maria writes a task for the team. In the task, she explains the problem: what she did, what she expected and what happened. She also adds a screenshot.

Ben is a backend developer. He reads the task and looks at the code. After one hour, he finds the bug. It is a small mistake in one function. Ben fixes it, and Maria tests the app again. Now it works!', 'A1', 2, '[{"statement":"Ben finds the bug in the code.","answer":true},{"statement":"Maria fixes the bug.","answer":false}]'::jsonb),
  ('Office or Home?', 'Our office is in the city centre. It is not big, but it is nice. There are ten desks, a kitchen and two meeting rooms.

I come to the office three days a week. On the other two days, I work from home. At home, I have a desk, a computer and a good chair. It is quiet, so I can think about my tasks.

In the office, I talk to my friends from the team. We have lunch together, and we often help each other with difficult questions. I think both are good: the office is for people, and home is for quiet work.', 'A1', 3, '[{"statement":"The writer works from home two days a week.","answer":true},{"statement":"The office has five meeting rooms.","answer":false}]'::jsonb),
  ('English for Work', 'Many developers need English. Documentation, error messages and questions on the internet are often in English. In many companies, the team speaks English at meetings too.

You don''t need perfect English to start. Try to learn a few new words every day, and read short texts about things you know. It is easier to understand a text about code than a text about history or art.

Practice is important. Listen to podcasts, write your commit messages in English and don''t be afraid of mistakes. Every week, your level improves a little.', 'A1', 4, '[{"statement":"You need perfect English before you start.","answer":false},{"statement":"It is easier to read about things you know.","answer":true}]'::jsonb),
  ('My First Week', 'Last month I started a new job. My first week was busy but interesting.

On Monday, I met the team and got my laptop. I didn''t write any code that day. I installed programs and read the documentation.

On Tuesday, my team lead explained the project to me. It is an app for doctors and their patients. I had a lot of questions, and she answered all of them.

On Wednesday, I fixed my first bug. It was very small, but I was happy. On Thursday, I made my first pull request, and on Friday, it went into the release. It was a good start!', 'A2', 5, '[{"statement":"On Monday, the writer wrote a lot of code.","answer":false},{"statement":"The writer''s first pull request went into the release on Friday.","answer":true}]'::jsonb),
  ('The Sprint', 'Our team works in sprints. A sprint is two weeks long. At the start of every sprint, we have a planning meeting. We look at the list of tasks and decide what we can finish in two weeks.

Every task has a size. Small tasks take one or two days, and big tasks take a week. We don''t take too many tasks, because we want to finish the sprint on time.

At the end of the sprint, we show our new features to the client. Then we have one more meeting and talk about the sprint: what went well, what went badly and what we can change next time.', 'A2', 6, '[{"statement":"A sprint is one month long.","answer":false},{"statement":"The team shows new features to the client at the end of the sprint.","answer":true}]'::jsonb),
  ('Why Do We Write Tests?', 'A test is a small program that checks another program. For example, a function adds two numbers. A test calls the function with 2 and 3 and checks that the answer is 5.

Why do developers write tests? Because code changes all the time. When you change one part of the app, you can break another part and not notice it. Tests run automatically after every commit and find these problems early.

Writing tests takes time, but it saves more time later. It is much cheaper to find a bug on your computer than in production, when real users see it.', 'A2', 7, '[{"statement":"Tests help to find problems early.","answer":true},{"statement":"Writing tests takes no time at all.","answer":false}]'::jsonb),
  ('What Is an API?', 'Many programs need to talk to each other. For example, a weather app on your phone does not know the weather. It asks a server. The app sends a request, and the server sends a response with the data.

The rules for this conversation are called an API. An API says what requests you can send and what responses you get back. Each address for a request is called an endpoint, for example /weather/today.

Some APIs are free. Others need a token — a secret key that shows who you are. Without the correct token, the server answers with an error.', 'A2', 8, '[{"statement":"The weather app knows the weather without a server.","answer":false},{"statement":"A token is a secret key.","answer":true}]'::jsonb),
  ('Git in Five Minutes', 'Git is a tool that saves the history of your code. The code and its history live in a repository.

When you start a new task, you usually create a branch. A branch is your own copy of the code, so your changes do not break the work of other people. When you finish a small step, you make a commit. A commit is like a photo of your code at one moment, with a short message about the change.

When the task is ready, you open a pull request. Your colleagues review the code and write comments. When everybody agrees, you merge the branch into the main code.', 'A2', 9, '[{"statement":"You usually create a branch for a new task.","answer":true},{"statement":"You merge the branch before the review.","answer":false}]'::jsonb),
  ('The Cache', 'Imagine a server that takes two seconds to answer a request. If a thousand users send the same request, the server does the same slow work a thousand times.

A cache helps with this problem. The first time, the server does the work and saves the answer in the cache. The next time somebody sends the same request, the server takes the answer from the cache. This is very fast.

But a cache has one danger: old data. If the data in the database changes, the answer in the cache is not correct anymore. So developers need to decide when to update the cache or remove old answers from it.', 'A2', 10, '[{"statement":"A cache can make answers faster.","answer":true},{"statement":"Data in a cache is always correct.","answer":false}]'::jsonb),
  ('A Bad Friday', 'Last Friday, at five o''clock in the evening, our website stopped working. Users saw an error page, and nobody could buy anything.

First, we looked at the logs. The server was fine, but the database was very slow. Then we found the problem: a new update sent the same request to the database thousands of times.

We didn''t try to fix the code on a Friday evening. Instead, we went back to the old version. After ten minutes, the website worked again. On Monday, we fixed the bug, added a test and deployed the update again.', 'A2', 11, '[{"statement":"The problem was in the requests to the database.","answer":true},{"statement":"The team fixed the code on Friday evening.","answer":false}]'::jsonb),
  ('An Email to the Client', 'Hi Sarah,

Thank you for your message. We looked at the problem with the login page yesterday. You were right: some users couldn''t log in from their phones. The reason was an old version of one library.

We updated the library and tested the login page on five different phones. Everything works now. The new version is on the test server today, and we plan to deploy it to production on Thursday.

Please let me know if you have any questions.

Best regards,
Alex', 'A2', 12, '[{"statement":"Some users couldn''t log in from their phones.","answer":true},{"statement":"The new version is already in production.","answer":false}]'::jsonb)
on conflict (title) do update set body = excluded.body, cefr_level = excluded.cefr_level, position = excluded.position, questions = excluded.questions;

-- Link each text to the dictionary words it contains (headword + simple inflections).
update texts set word_ids = coalesce((
  select array_agg(w.id) from words w
  where texts.body ~* ('\m' || regexp_replace(w.headword, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '(s|es|ed|d|ing)?\M')
), '{}');
